<script setup lang="ts">
import { computed } from 'vue'
import type { ElderApp } from '../composables/useElderApp'
import PageHero from '../components/PageHero.vue'
import CourseList from '../components/CourseList.vue'
const props = defineProps<{ app: ElderApp }>()
const categories = ['全部', '出行打车', '就医挂号', '日常生活', '聊天联络', '防骗安全']
const courses = computed(() => props.app.state.data?.courses.filter(c => (props.app.state.category === '全部' || c.category === props.app.state.category) && (c.title + c.description + c.category).includes(props.app.state.query.trim())) ?? [])
const selected = computed(() => props.app.state.data?.courses.find(c => c.id === props.app.state.selected))
</script>
<template><template v-if="app.state.page === 'learn'"><PageHero title="数字教学" subtitle="一步一步学，生活更方便"/><div class="content"><input v-model="app.state.query" type="search" aria-label="搜索教程" placeholder="搜索您想学的内容"/><div class="categories"><button v-for="category in categories" :key="category" :aria-pressed="app.state.category === category" :class="{ selected: app.state.category === category }" @click="app.state.category = category">{{ category }}</button></div><section class="card"><h2>学习教程</h2><CourseList v-if="app.state.demo" :courses="courses" @select="app.go('course-detail', $event)"/><p v-else class="empty">教学服务尚未接入</p></section><button class="row card" @click="app.go('learning-history')"><strong>学习记录</strong><span>›</span></button></div></template><div v-else-if="app.state.page === 'course-detail'" class="content"><template v-if="selected"><p class="demo-note">课程为演示数据，没有真实视频。</p><div class="video" :class="selected.color"><span>{{ selected.symbol }}</span><button class="primary" @click="app.state.feedback = '没有真实视频，当前仅展示播放界面'">▷ 播放预览</button><small>{{ selected.duration }} · 模拟时长</small></div><section class="card"><h2>{{ selected.title }}</h2><p>{{ selected.description }}</p></section><section class="card"><h2>本课内容</h2><p v-for="(item, i) in selected.outline" :key="item">{{ i + 1 }}．{{ item }}</p></section></template><p v-else class="empty">课程服务尚未接入</p></div><div v-else class="content"><template v-if="app.state.data"><p class="demo-note">以下为模拟学习记录</p><section v-for="course in app.state.data.courses.filter(c => c.progress > 0)" :key="course.id" class="card"><CourseList :courses="[course]" @select="app.go('course-detail', $event)"/><progress :value="course.progress" max="100" :aria-label="course.title + '学习进度'"/><p>已学习 {{ course.progress }}% · 模拟</p></section></template><p v-else class="empty">学习记录服务尚未接入</p></div></template>
